import json,glob
counts={'hyp':0,'hyp_cm':0,'evl':0,'evl_as':0,'dissent':0}
for p in glob.glob('state/hypotheses.d/*.jsonl'):
    for l in open(p):
        r=json.loads(l); counts['hyp']+=1; counts['hyp_cm']+= bool(r.get('counter_material_ids'))
for p in glob.glob('state/evaluations.d/*.jsonl'):
    for l in open(p):
        r=json.loads(l); counts['evl']+=1
        if r.get('agency_stance'): counts['evl_as']+=1
        if r.get('agency_stance')=='dissent': counts['dissent']+=1
print(counts)
